pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small, hard-to-fill leftovers) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 25.0;
    } else if post_residual > 12 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small waste relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: only attractive when residuals are large
    // and the current fit is poor, or the next item needs the freed space.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0) * 0.9;
        let next_fits_better = next_item_size > 0 && next_item_size <= bin_capacity
            && next_item_size as f64 > mean_residual * 0.8;
        if poor_fit || next_fits_better {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Slight stream-progression bias toward tighter packing later in the stream.
    score += (step_index as f64 / total_items.max(1) as f64) * 4.0;

    score
}

