        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the residual
    // left behind (chained perfect packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally
            // to how much of the residual is wasted.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 50.0 * (1.0 - waste);
        } else {
            // Next item fits with room to spare: mild bonus scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Penalize creating small unusable residuals (below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against the mean residual of open bins: prefer bins whose
    // residual is tighter than average (fill fuller bins first).
    let tightness = mean_residual - bin_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only
    // when the current fit is poor (large post_residual relative to capacity
    // or heavy dead space), otherwise discourage spreading items thin.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        if poor_fit > 0.6 {
            score -= 120.0 * (poor_fit - 0.6) * 2.5;
        } else {
            score += 150.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    // Small penalty per open bin to discourage needless bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain fit: post_residual == next_item_size
        if post_residual as f64 == nxt {
            score -= 60.0; // strong reward for perfect 2-chain
        } else if gap <= 5.0 {
            score -= 35.0 - gap * 4.0;
        } else if gap <= 15.0 {
            score -= 12.0 - gap * 0.5;
        } else {
            // Post-residual too small or too large for next item: penalize dead space
            score += gap * 0.6;
        }
        // If next item cannot fit in post_residual at all, penalize proportionally
        if (post_residual as f64) < nxt {
            score += (nxt - post_residual as f64) * 0.8;
        }
    } else {
        // Last item: minimize post_residual directly (already base score)
        score += (post_residual as f64) * 0.1;
    }

    // Reward tight fits relative to mean residual of open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty for spreading across many bins when alternatives exist
        score += fitting_bins_count as f64 * 0.5;
    }

    // Penalize opening a new bin unless current open bins are mostly full or too fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when mean residual is small (bins nearly full)
        score += 40.0;
        score -= mean_residual * 0.5;
        // Early in stream, opening new bins is cheaper; late, avoid it
        score -= (1.0 - progress) * 30.0;
    } else {
        // Existing bin: compare its residual to mean; prefer bins with residual close to item
        score += ((bin_residual as f64 - mean_residual) * 0.15).max(0.0);
    }

    // Penalize leaving very small unusable post-residual (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

