pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post-residual scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small dead space non-linearly (wasted capacity)
    if pr > 0.0 {
        score += 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr;
    }

    // Perfect-fit reward, stronger later in the stream
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance fitting bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Residuals in the "tiny" band are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0.0 .. 1.0

    // Class thresholds: <0.1 dead, <0.2 poor, <0.5 medium, else roomy
    if frac < 0.1 {
        score -= 6.0; // perfect packing: nearly-full bin is great
    } else if frac < 0.2 {
        score -= 2.5;
    } else if frac < 0.5 {
        score += 1.5;
    } else {
        score += 4.0;
    }

    // Integer-division harmonic class: post_residual mod 10 captures
    // alignment with typical item granularity.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 1.0; // aligned residual pairs well with 10-multiple items
    } else if mod10 >= 5 {
        score += 0.5;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size < post_residual {
            let next_frac = next_item_size as f64 / pr;
            if next_frac > 0.7 {
                score -= 2.0; // next item fills most of leftover
            } else if next_frac < 0.3 {
                score += 1.0; // next item leaves more fragmentation
            }
        } else {
            score += 0.8; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate handling: empty bins are mediocre by default so we
    // only open a new bin when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= 0.05 * (mean_residual - pr);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight fit: reward proportional closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Lookahead: penalize leaving a gap just below the next item's size (near-miss).
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: if this bin is much emptier than average, slight penalty
    // (prefer filling fuller bins; keep large gaps on some bins for big items).
    if (bin_residual as f64 - mean_residual) > 30.0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Reduce cost when all existing fits would leave small dead gaps.
        if post_residual >= bin_capacity - item_size {
            // empty bin: post_residual = capacity - item_size
            if post_residual > 12 {
                score -= 20.0;
            }
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: item + next item exactly fills the bin.
    if next_item_size > 0 {
        let combined = post_residual as f64 - next_item_size as f64;
        if combined == 0.0 {
            score -= 1000.0; // exact two-item closure
        } else if combined < 0.0 {
            // next item cannot fit here: dead space unless tiny
            score += 0.6 * (-combined);
        } else {
            // next item fits with room to spare: mild reward scaled by tightness
            score -= 0.3 * (1.0 - combined / bin_capacity as f64);
        }
    } else {
        // last item: prefer fullest packing
        score -= 0.5 * post_residual as f64;
    }

    // Reward bins tighter than average, penalize looser-than-average choices
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual <= 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post_residual is too small for the next item, it is likely dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual {
            // Dead space unless this residual is tiny anyway.
            score += 0.4 * post_residual as f64;
        } else {
            // Next item still fits: mild reward for keeping usable space.
            score -= 0.2 * next_item_size as f64;
        }
    } else {
        // Last item: only tightness matters.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless fits are poor.
        score += 60.0;
        // More attractive early (plenty of stream left to fill the bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Attractive if open bins are crowded (low mean residual).
        score -= 0.5 * mean_residual;
        // Attractive if few bins fit the item anywhere.
        score += 8.0 * fitting_bins_count as f64;
    } else {
        // Reward bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - tightness);
        // Mildly prefer using bins with large residual to consolidate.
        score -= 0.05 * bin_residual as f64;
    }

    // Late in the stream, avoid opening new bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 80.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Coupling: waste matters more as stream progresses
    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect fit reward (smooth, quadratic in post-residual)
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead: reward post_residual that can accommodate the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0);
        let usable = if post >= nxt { 1.0 } else { 0.0 };
        score -= 6.0 * usable * (1.0 - (fits / cap));
        score += 4.0 * (nxt / cap) * (post - nxt).abs() / cap;
    }

    // Last-chance fitting bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Penalize opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        score += 3.0 + 0.4 * open_bins_count as f64 + 5.0 * (mean_residual / cap);
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 2.0; // empty bin still useful for large next item
        }
    }

    // Mild preference for bins tighter than average
    score += 2.0 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals in [1..10] are near-dead space; large residuals are flexible.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 25.0;

    // Exact fit: perfect placement, reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo arithmetic on residual: residuals divisible by common item
    // granularity (10) are "harmonic" and likely reusable later.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 6.0;

    // Can the lookahead item fit in the post-residual? Reward that chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Bonus if the pair nearly fills the bin harmonically.
        if (bin_residual - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Lookahead won't fit here; penalize proportionally to the miss.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.15;
    }

    // Integer-division threshold on post_residual: classify leftover into
    // coarse capacity fractions. Small fractions (< 25% capacity) are risky.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.25 && post_residual > 0 {
        score += 8.0;
    } else if frac >= 0.5 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin leaves bad dead space) or early stream.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score += 12.0 + pressure;
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += (open_bins_count as f64) * (mean_residual / 100.0) * 0.5;

    // Slight preference for tighter bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio;
    }

    // Penalize opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual below the mean (compact bins).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would leave another dead gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain fit: post_residual == next_item_size
        if post_residual as f64 == nxt {
            score -= 60.0; // strong reward for perfect 2-chain
        } else if gap <= 5.0 {
            score -= 35.0 - gap * 4.0;
        } else if gap <= 15.0 {
            score -= 12.0 - gap * 0.5;
        } else {
            // Post-residual too small or too large for next item: penalize dead space
            score += gap * 0.6;
        }
        // If next item cannot fit in post_residual at all, penalize proportionally
        if (post_residual as f64) < nxt {
            score += (nxt - post_residual as f64) * 0.8;
        }
    } else {
        // Last item: minimize post_residual directly (already base score)
        score += (post_residual as f64) * 0.1;
    }

    // Reward tight fits relative to mean residual of open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty for spreading across many bins when alternatives exist
        score += fitting_bins_count as f64 * 0.5;
    }

    // Penalize opening a new bin unless current open bins are mostly full or too fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when mean residual is small (bins nearly full)
        score += 40.0;
        score -= mean_residual * 0.5;
        // Early in stream, opening new bins is cheaper; late, avoid it
        score -= (1.0 - progress) * 30.0;
    } else {
        // Existing bin: compare its residual to mean; prefer bins with residual close to item
        score += ((bin_residual as f64 - mean_residual) * 0.15).max(0.0);
    }

    // Penalize leaving very small unusable post-residual (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize proportional to wasted potential
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when the stream
    // is early (plenty of future items to fill it) or current bins have bad residuals.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_benefit = open_bins_count as f64 * 2.5; // consolidating into open bins is cheaper
        score += 12.0 + open_benefit - 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, open bins are all tight; new bin less bad.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 5.0;
        // If next item is large and won't fit anywhere else, new bin may serve it.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, waste is cheap; late, tight packing matters more.
    let progress_weight = 1.0 + 2.5 * progress * progress;
    score *= progress_weight;

    // Smooth penalty for leaving residuals that are hard to reuse:
    // penalize mid-range dead space via a smooth bump around half capacity.
    let bump = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 40.0 * bump * (1.0 - norm_pr);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let perfect = (norm_pr).max(0.0);
    score -= 30.0 * (1.0 - perfect) * (1.0 - perfect) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Mild scarcity pressure: fewer fitting bins => prefer existing bins over new.
    score -= 8.0 / fit;

    // Lookahead: if next item fits smoothly into the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a smooth cost that shrinks
    // with progress and with how fragmented open bins are.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 25.0 * (1.0 - progress) - 20.0 * fragmentation * progress;
    }

    // Tie-breaker: prefer bins with residual below the mean (denser bins).
    score += 5.0 * ((pr as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual modulo small integers:
    // residuals divisible by 10 (capacity fractions) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit is always best
    } else {
        if pr % 10 == 0 {
            score -= 40.0;
        }
        if pr % 5 == 0 {
            score -= 15.0;
        }
        // integer-division thresholds: tiny dead space is nearly useless
        if pr < 10 {
            score += 120.0;
        } else if pr < 20 {
            score += 60.0;
        } else if pr < 30 {
            score += 25.0;
        }
    }

    // Reward tight fits: ratio of item to residual (harmonic fraction).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Harmonic class of next item: if the next item exactly fits post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 180.0;
        } else if next_item_size <= pr {
            score -= 30.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this residual: mildly penalize large leftovers
            score += 0.15 * pr as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new empty bin, more so early in the stream and
    // when many open bins still have room.
    if bin_residual == bin_capacity {
        score += 200.0 + 50.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // a new bin is acceptable only if the item is large relative to capacity
        score -= 1.2 * item_size as f64;
    } else {
        // prefer filling already-open bins, especially those below mean residual
        if (bin_residual as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is in a "good" harmonic class
    // relative to item size (item divides residual evenly).
    if bin_residual % item_size.max(1) == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space severity grows as the gap falls short of the next item.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 2.0 * shortfall;
        // Gaps below the minimum conceivable item size are permanently dead.
        if post_residual < 1 {
            score += 50.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 1.5 * tightness * post_residual as f64;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty to spread load when alternatives exist.
        score += 1.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a fresh
    // bin keeps the active set small, but only when the fit is poor.
    let poor_fit = post_residual as f64 > 0.5 * (bin_capacity as f64);
    if poor_fit && open_bins_count > 2 {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it is only chosen when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But if next item is large and this item leaves a bad gap, opening
        // fresh is attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
        // Early in the stream, allow opening bins more freely.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
    }

    // Slight preference to keep bins balanced around mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how much would remain after the next placement
            let after_next = (post_residual - next_item_size) as f64;
            score -= 60.0 - after_next * 0.5;
        } else {
            // next item will NOT fit here: penalize the stranded gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
