    // Penalize dead space relative to mean residual (worse than average leftovers is bad)
    let mr = mean_residual;
    if mr > 0.0 {
        let ratio = post_residual as f64 / mr;
        score += (ratio - 1.0) * 15.0;
    }

    // Last-chance bin: avoid opening a new bin if this fit is decent
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 80.0;
    }

    // Prefer keeping large residuals for future large items; small residual = tightly packed (good)
    score += (bin_residual as f64) * 0.05;

    // Mild stream-progression pressure: as stream advances, tighten packing
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;
    }

    // Penalize opening new bins when open bins exist with good fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

