        }
        // Don't open a new bin for a tiny item late in the stream.
        if item_size < 20 && progress > 0.5 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = pr / cap; // normalized post residual
    let p = progress;

    // Base: prefer tight fits (low post_residual), with progress-dependent curvature
    let mut score = pr * (1.0 + 0.5 * p * p);

    // Non-linear interaction: penalize large residuals more as stream progresses
    score += cap * 0.6 * t * t * (1.0 + p);

