    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact / near-exact fit rewards (sharpened residual classes)
    if post_residual == 0 {
        score -= 85.0;
    } else if post_residual <= 3 {
        score -= 55.0;
    } else if post_residual <= 7 {
        score -= 26.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    }

    // Harmonic class reward
    let class = (post_residual / 10).min(10);
    score -= (10 - class) as f64 * 2.6;

    // Two-step lookahead with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as u32 == next_item_size {
            score -= 75.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 34.0 * (1.0 - slack / cap);
            if post_residual % next_item_size <= 4 {
                score -= 18.0;
            }
            // multi-fit chain: residual could host next item multiple times
            if post_residual >= 2 * next_item_size {
                score -= 10.0;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= 15 {
                score -= 7.0;
            }
        } else {
            score += 10.5 * (1.0 - pr / cap) + (nx - pr) * 0.5;
        }
    } else {
        score += pr * 0.1;
    }

    // Tightness reward relative to capacity
    let tightness = (bin_residual as f64 - it) / cap;
    score -= (1.0 - tightness) * 18.0;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 38.0;
    } else {
        score += fitting_bins_count as f64 * 0.35;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 14.0 - 13.0 * progress - 2.4 * pressure.min(5.0);
        score -= 14.0 * (it / cap);
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 11.0;
        }
        if it < 28.0 && open_bins_count > 3 {
            score += 12.0;
        }
        // Late stream: avoid proliferating bins unless item is big
        if progress > 0.7 && it < 50.0 {
            score += 9.0 * progress;
        }
        // If next item is large, opening a fresh bin now may waste space
        if next_item_size as f64 > 0.5 * cap {
            score += 6.5;
        }
        // Refuse a fresh bin when the item would leave a stranded
        // mid-range remainder that no open bin could offer anyway
        if pr > 0.0 && pr < 20.0 && pr >= next_item_size as f64 {
            score += 5.5;
        }
    } else {
        // Tight specialization: penalize drift from mean residual
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += 0.075 * drift;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        // Reward bins whose residual is a small, reusable remainder
        if post_residual > 0 && post_residual <= 20 && post_residual >= next_item_size.min(20) {
            score -= 5.0;
        }
        // Waste-ratio term — penalize bins whose residual-to-capacity ratio is high
        let waste_ratio = pr / cap;
        score += 9.5 * waste_ratio * (0.4 + 0.6 * progress);
        // Reward bins whose residual is exactly a "harmonic" leftover
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 3.5;
        }
        // Penalize bins whose residual leaves a remainder just below
        // the next item size — near-miss dead space that will strand
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.5 * (1.0 - progress) * (1.0 - pr / cap);
        }
        // NEW: prefer bins whose post-residual stays divisible by a
        // plausible small follow-up, keeping space re-usable
        if next_item_size > 0 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        let remaining = 1.0 - progress;
        score += 17.0 + 7.0 * remaining;
    }

    // Penalize mid-range dead zones that are too small for typical items
    if post_residual > 12 && post_residual < 25 {
        let usable = (next_item_size as f64) <= pr;
        if !usable {
            score += 7.0 * (1.0 - progress);
        }
    }

    score
}

