    // the stream mean waste more potential; scale with remaining stream length
    if post_residual > 0 && mean_residual > 0.0 && pr > mean_residual * 1.6 {
        score += 2.5 * ((pr - mean_residual * 1.6) / cap) * (1.0 + remaining);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Detect brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize new bins by the average waste they would lock in,
        // scaled by how many alternatives exist.
        let alt_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 35.0 + 12.0 * alt_pressure;
        // Slight discount late in the stream is unnecessary; keep constant.
        return score;
    }

    // Strong best-fit core: reward tight fits nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Last-chance bonus: this is the only open bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 0.5 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives: prefer keeping flexibility.
        score += 2.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 90.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = pr - nxt;
            score -= 25.0 - 0.4 * slack; // good chaining, less reward for leftover
        } else {
            // Next item won't fit here; leaving big residual is dead space.
            score += 0.25 * pr;
        }
    }

    // Global state: prefer bins with residual below the mean (consolidate emptier space usage).
    score += 0.15 * (pr - mean_residual);

    // Time horizon: early in stream, be more conservative about tight fits (keep bins open);
    // late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_capacity as f64 - pr) / bin_capacity as f64;

    // Mild pressure to reduce number of open bins early on.
    score += 0.4 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

