        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        if post_residual > 0 && mean_residual > 0.0 && post_residual as f64 >= mean_residual * 0.9 {
            score -= 4.0 * (1.0 - progress);
        }
        if bin_residual > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        // Mutated: prefer bins whose post-residual can still fit the next item with room for one more
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 4.0 * (1.0 - progress);
        }
        // Mutated: discourage near-miss fits that leave exactly an awkward gap
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > 12 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        let remaining = 1.0 - progress;
        score += 19.5 + 8.0 * remaining;
    }

    if post_residual > 11 && post_residual < 25 {
        let usable = (next_item_size as f64) <= pr;
        if !usable {
            score += 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial coupling: reward small post_residual, with
    // progress-modulated shaping (late in stream, pack tighter).
    let mut score = post * (1.0 + 0.35 * progress) * (1.0 - norm_post * norm_post);

    // Dead-space penalty: small but nonzero post_residual is wasted space.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * (10.0 - post) * 0.05 } else { 0.0 };
    score += dead;

    // Perfect fit reward (smooth via quadratic in post).
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Slight preference to fill bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual: prefer bins below average residual (fuller bins).
    score += 0.1 * (mean_residual - post).abs();

    // New-bin candidate: mild baseline penalty so it's chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
