pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // "usable bands" via integer division thresholds on capacity fractions.
    // Class 0: near-perfect fit (<=10)  -> strongly reward
    // Class 1: small leftover (11..25)  -> mild reward
    // Class 2: awkward leftover (26..49)-> penalize (dead space)
    // Class 3: large leftover (>=50)    -> neutral-ish (still usable)
    let pr = post_residual as f64;
    let frac = pr / cap;

    if post_residual == 0 {
        score -= 60.0; // perfect packing
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual < bin_capacity / 2 {
        // awkward band: dead space penalty, worse the closer to half
        let awkward = 1.0 - (pr - 25.0) / 25.0;
        score += 12.0 * awkward;
    } else {
        // large residual: reward proportionally to usable fraction
        score -= 8.0 * frac;
    }

    // Harmonic residue check: leftover that is a multiple of common small
    // item sizes (10, 20, 25, 50) is more likely to be filled later.
    if post_residual % 10 == 0 { score -= 10.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 && post_residual > 0 { score -= 8.0; }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this is a golden pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another leftover: judge resulting pair
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 { score -= 20.0; }
            else if nxt_post < bin_capacity / 2 { score += 6.0; }
        } else {
            // next item cannot use this bin's leftover: slight penalty if
            // leftover is in the awkward band
            if post_residual > 25 && post_residual < bin_capacity / 2 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter bins; post_residual already encodes this
        score += 0.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are crowded
        // (mean residual small) or when few bins fit the item.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (cap - mean_residual) / cap; // high when bins nearly full
        let penalty = 55.0 - 30.0 * crowding - 10.0 * progress
            - 15.0 * (fitting_bins_count == 1) as i32 as f64;
        score += penalty.max(0.0);
    }

    // Tie-break by fill level: prefer fuller bins slightly.
    score -= 0.05 * (cap - pr);

    score
}

