            score += 3.0 * progress;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        let remaining = 1.0 - progress;
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 {
        let usable = (next_item_size as f64) <= pr;
        if !usable {
            score += 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo a small base (dead-space "harmonics").
    let base: u32 = 10;
    let residue_class = post_residual % base;
    let harmonic_index = post_residual / base; // 0..=10 for C=100

    // Perfect fit: post_residual == 0 -> extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: leftover that is too small for the smallest
    // possible item (1) is fine only if 0; otherwise small leftovers
    // below a usable threshold are wasted. Penalize tiny nonzero leftovers.
    if post_residual > 0 && post_residual < 3 {
        score += 40.0;
    }

    // Harmonic decay: reward small harmonic_index (tight fits), with
    // quadratic growth so big leftovers are penalized progressively.
    let h = harmonic_index as f64;
    score += 0.35 * h * h;

    // Residue-class coupling: leftovers whose class aligns with common
    // item sizes are more reusable. Classes 0 and 5 (multiples of 5)
    // are "harmonic" with typical item sizes; reward them slightly.
    if residue_class == 0 {
        score -= 3.0;
    } else if residue_class == 5 {
        score -= 1.5;
    } else {
        score += 0.5 * (residue_class as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin becomes a perfect chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        }
        // If next item cannot fit the leftover at all, penalize large leftovers
        // mildly (they may become dead space).
        if next_item_size > post_residual && post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): it has bin_residual == bin_capacity,
    // post_residual == bin_capacity - item_size. Penalize opening a new bin
    // unless the current stream is early or open bins are already numerous
    // relative to progress (heuristic load balancing).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let load = open_bins_count as f64 / (progress * (total_items.max(1) as f64)).max(1.0);
        score += 30.0 + 10.0 * load.min(5.0);
        // But if the item is large relative to mean residual of open bins,
        // opening fresh may be wise: soften penalty.
        let mean_r = mean_residual;
        if item_size as f64 > mean_r * 0.8 {
            score -= 35.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (converging toward consolidation).
    let diff = mean_residual - bin_residual as f64;
    score -= 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
