        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * (1.0 - progress);
        }
        // Penalize residuals in the awkward 18-30 dead zone late in stream
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        // Perfect and near-perfect fits
