            score -= 7.0;
        }
        // Boost bins whose post-residual can host next item exactly twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * (1.0 - progress);
        }
        // Stronger reward when the fit is within 1 unit
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
