    if post_residual > 0 && post_residual < 9 {
        let remaining = 1.0 - progress;
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Dead space below the minimum item size is permanently unusable.
    let dead = (post_residual as f64).min(9.0);
    score += dead * 2.5;

    // Next-item lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap too small for the next item: extra penalty scaled by gap size.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64).min(20.0) * 0.4;
    }

    // Prefer bins tighter than the mean residual (consolidation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early stream: be slightly more willing to open bins (diversity), late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

