            score += 3.8 * (pr / cap) * (0.5 + progress);
        }
        // Favor bins whose post-residual matches plausible future item sizes
        if post_residual > 0 && post_residual <= 100 && mean_residual > 0.0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual).min(1.0);
            score -= 3.8 * align;
        }
        // Extra reward for exact two-item chains
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * (1.0 - progress);
        }
        // Penalize residuals in the awkward 18-30 dead zone late in stream
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        // Prefer bins whose residual equals item exactly (perfect fit)
        if bin_residual == item_size {
            score -= 15.0;
        }
        // Reward near-perfect fits (within 2 units)
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        // Boost bins whose post-residual can host next item exactly twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * (1.0 - progress);
        }
        // Stronger reward when the fit is within 1 unit (near-zero waste)
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
        // Penalize leaving residuals that no plausible item can use
        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * (1.0 - progress);
        }
        // Harmonic leftover bonus
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        // Mutated: prefer bins that stay usable by the immediate stream, not just next item
        if post_residual > 0 && mean_residual > 0.0 && post_residual as f64 >= mean_residual * 0.9 {
            score -= 4.0 * (1.0 - progress);
        }
        // Mutated: discourage fragmenting a bin whose residual could still host a large item
        if bin_residual > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        // Mutated: penalize residual-fragmentation gap between mean residual and post residual
        if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.5 {
            score += 6.0 * (1.0 - (post_residual as f64) / (mean_residual * 0.5)) * (0.5 + progress);
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        let remaining = 1.0 - progress;
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 {
        let usable = (next_item_size as f64) <= pr;
        if !usable {
            score += 9.0 * (1.0 - progress);
        }
    }

    // Mutated: global dead-space ratio pressure — bins whose post residual exceeds
    // half the item's complement are charged proportionally to remaining stream
    if post_residual > 0 && post_residual as f64 > 0.55 * cap {
        score += 5.0 * (pr / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = 40.0 * x * x - 30.0 * x * x * x;

    // Early stream: prefer tight fits less aggressively; late stream: reward tight fits strongly
    let late_bias = progress * progress;
    score -= 20.0 * late_bias * (1.0 - x);
    score += 15.0 * (1.0 - progress) * x;

    // Penalize dead space relative to next item: residual too small to fit lookahead
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (x - nx).max(0.0);
        score -= 12.0 * (1.0 - usable) * (1.0 - x);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 8.0 * (1.0 - x);
    }

    // Mild pressure toward consolidating into existing bins when many are open
    score += 0.05 * open_bins_count as f64 * (1.0 - x);

    // Deviation from mean residual: prefer bins close to mean to balance load
    score += 0.1 * (pr - mean_residual).abs();

    // Slight reward for a fresh empty bin early, penalty late
    if bin_residual == bin_capacity {
        score += 5.0 * progress - 3.0 * (1.0 - progress);
    }

    score
}

