    // penalize harmonic mismatch (next item overshoots by a small dead margin).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 20.0;
            } else if next_post <= 9 {
                score += 6.0;
            } else if next_post % 10 == 0 {
                score -= 6.0;
            }
