    } else {
        score += fitting_bins_count as f64 * 0.35;
    }

    // New-bin candidate logic (empty bin call)
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 14.0 - 14.0 * progress - 3.0 * pressure.min(5.0);
        score -= 17.0 * (it / cap);
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 13.5;
        }
        if it < 28.0 && open_bins_count > 3 {
            score += 14.5;
        }
        if progress > 0.7 && it < 50.0 {
            score += 11.5 * progress;
        }
        if next_item_size as f64 > 0.5 * cap {
            score += 7.5;
        }
        if next_item_size > 0 && it <= mean_residual {
            score += 5.5 * (1.0 - it / mean_residual);
        }
        if it < 40.0 && mean_residual > 0.0 && (mean_residual - it).abs() < 6.0 {
            score += 10.0;
        }
        if it < 15.0 && fitting_bins_count > 0 {
            score += 22.0;
        }
        if fitting_bins_count >= 3 && it < 0.35 * cap {
            score += 6.0 + 2.0 * fitting_bins_count as f64;
        }
        if mean_residual < 8.0 && it > mean_residual {
            score -= 8.0 * remaining;
        }
        if fitting_bins_count > 0 && mean_residual > 0.0 && (mean_residual - it).abs() <= 3.0 {
            score += 18.0;
        }
        if it > 0.6 * cap {
            score -= 9.0 * (0.5 + progress);
        }
        if open_bins_count > 12 && it > 0.7 * cap {
            score -= 6.0;
        }
        // Open a new bin for large items when existing residuals
        // are all too fragmented to chain with the next item.
        if it > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 10.0 * remaining;
        }
        // Dead-gap avoidance: fresh bin when placing on a fitting bin
        // would strand space the next item cannot use.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual > 0.0 {
            let nx = next_item_size as f64;
            let dead = (mean_residual - it).max(0.0);
            if dead > 0.0 && nx > dead {
                score -= (2.5 + 5.5 * remaining) * (dead / mean_residual.max(1.0));
            }
        }
        // Hoard roomy bins for larger future items.
        if open_bins_count > 8 && it < 0.2 * cap && next_item_size as f64 > mean_residual {
            score += 5.0 * remaining;
        }
        // Large next item + small current item: keep fresh bins unfragmented.
        if next_item_size > 0 && fitting_bins_count > 0
            && (next_item_size as f64) > mean_residual * 0.8
            && it < 0.25 * cap {
            score -= 7.0 * remaining;
        }
        // Early stream with big item: fresh bin avoids fragmenting a partial bin.
        if progress < 0.3 && it > 0.55 * cap && fitting_bins_count > 0 {
            score -= 6.0;
        }
        // Exact-fit forecast — if the current item nearly fills a fresh
        // bin to a multiple of the next item size, opening a new bin chains well.
        if next_item_size > 0 && next_item_size <= 20 {
            let post_new = cap - it;
            if post_new >= next_item_size as f64
                && (post_new as u32) % next_item_size <= 3 {
                score -= 11.0 * remaining;
            }
        }
        // When the mean residual is small, leftover bins are nearly
        // useless — prefer consolidating into a fresh bin for medium items.
        if mean_residual > 0.0 && mean_residual < it * 0.45 && it < 0.5 * cap
            && fitting_bins_count >= 2 {
            score -= 6.0 * remaining;
        }
        // NEW: fresh-bin chaining forecast vs. mean residual — if a fresh bin's
        // post-residual lands near the mean residual, future items likely fit it.
        let post_new = cap - it;
        if mean_residual > 0.0 && post_new >= mean_residual {
            let align = 1.0 - ((post_new - mean_residual) / mean_residual).min(1.0);
            score -= 8.0 * align * remaining;
        }
        // NEW: opening a fresh bin for a tiny item when a fitting bin exists
        // is wasteful unless the fresh post-residual chains with the next item.
        if it < 12.0 && fitting_bins_count > 0 && next_item_size > 0
            && (post_new as u32) < next_item_size {
