        // useless — prefer consolidating into a fresh bin for medium items.
        if mean_residual > 0.0 && mean_residual < it * 0.45 && it < 0.5 * cap
            && fitting_bins_count >= 2 {
            score -= 4.5 * remaining;
        }
        // NEW: pair-forecast — opening a fresh bin with a small item leaves a
        // residual exactly sized for the next item AND the item after that
        // (next*2 fits); strong chaining signal, scaled by remaining stream.
        if next_item_size > 0 && it <= next_item_size as f64 {
            let post_new = cap - it;
            if post_new >= 2.0 * next_item_size as f64 && next_item_size <= 25 {
                score -= (3.0 + 5.0 * remaining) * (it / next_item_size as f64).min(1.0);
            }
        }
        // NEW: if no open bin can chain with the next item after placement,
        // a fresh bin guarantees a chainable residual.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual > 0.0 {
            let nx = next_item_size as f64;
            let best_chain = mean_residual.max(0.0);
            if best_chain < nx && it <= nx {
