        if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual
            && open_bins_count > 6 {
            score += 5.0 * remaining;
        }
        // MUTATION: reward bins whose post-residual is an exact multiple of
        // common small item sizes (divisibility forecast).
        if post_residual > 0 && post_residual <= 24 {
            for d in [2u32, 3, 4, 5, 6, 8, 10, 12].iter() {
