        // NEW: two-step chain forecast — if placing here leaves a residual
        // that after absorbing the next item still divides evenly by the
        // mean residual, this bin supports a long fill chain.
        if next_item_size > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
            let after_next = pr - next_item_size as f64;
