                && ((after_next % mean_residual) < 1.5 || mean_residual - (after_next % mean_residual) < 1.5) {
                score -= 5.5 * remaining;
            }
        }
        // NEW: quantify true waste — residual unusable by next item AND by
        // the mean item incurs a proportional penalty, strongest mid-stream
        // where there is still time to pack tighter.
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && (post_residual as f64) < mean_residual {
            score += 2.2 * remaining * (pr / cap) * 100.0;
        }
        // NEW: complementarity bonus — placing this item exactly complements
        // the bin residual to a "round" capacity fraction (quarter fills).
        let frac = (bin_residual as f64) / cap;
        for target in [0.25, 0.5, 0.75, 1.0] {
