    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post residual and item footprint
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    // Early on, keep bins tight (favor low post_residual); later, allow slack for future items.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Cubic coupling: penalize mid-range dead space more as stream progresses
    score += 12.0 * pr_norm * (1.0 - pr_norm) * (pr_norm - 0.5) * progress;

    // Squared post-residual interaction with item footprint:
    // large items in roomy bins -> quadratic penalty growth
    score += 6.0 * pr_norm * pr_norm * item_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post residual, reward this placement smoothly
    let next_fits = (next_item_size as f64) <= pr;
    if next_item_size > 0 && next_fits {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * tight;
    }

    // Mean residual coupling: penalize placing into a bin far from mean residual (balance)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Slight penalty for opening new bins when open bins can fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 * (1.0 - progress) + 2.0 * item_norm;
    }

    score
}

