        // NEW: penalize leaving a residual just below the next item when the
        // stream is long — that gap is nearly guaranteed waste.
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && (next_item_size as i32 - post_residual as i32) <= 4 {
            score += 5.5 * remaining;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let post = post_residual as f64;
    score -= (bin_capacity as f64 - post) * 0.35;

    // Penalize small dead space: residuals 1..=10 are almost unusable
    // for items of size >= 10 (interface note: sizes 1..100 possible).
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 - 3.0 * post as f64;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Harmonic classes: classify post_residual by modulo classes of the
    // capacity quantum (capacity / 4). Residuals in the "quarter band"
    // (just above a quarter) pair well with typical items; just below a
    // quarter they are dead space.
    let q = bin_capacity / 4; // 25
    let r = post_residual % q;
    if post_residual > 0 {
        if r <= 3 {
            score += 20.0; // just above a quarter boundary: awkward
        } else if r >= q - 5 {
            score -= 12.0; // just below boundary: nearly full quarter class
        }
        // integer-division threshold: residual exactly divisible into
        // halves/quarters is a "harmonic" leftover, easy to reuse
        if post_residual % 50 == 0 || post_residual % q == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or nearly, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0);
        } else {
            // next item won't fit here; mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: fresh empty bin should only win when the item is
    // large relative to capacity or the fit is clean.
    if bin_residual == bin_capacity {
        score = 55.0 - (item_size as f64) * 0.4;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for a paired packing
        }
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: late in the stream, be more conservative with
    // new bins and squeeze existing ones harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin worth draining first.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

