pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements that still leave room for a mid/large item.
    if post_residual >= 10 {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // lookahead fit bonus
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // lookahead would be wasted
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate: only attractive when existing bins create bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
