pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to likely hold future items.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powi(3);
        score += 60.0 * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Next item won't fit here; slight penalty for wasting big residual.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (larger post_residual);
    // late in stream, prioritize filling bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 15.0;
    score -= progress * tightness * 10.0;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and stream is early (future items may use the fresh bin well).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit && fitting_bins_count > 0 {
            score += 20.0 + 30.0 * progress;
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

