        if fitting_bins_count >= 3 && it < 0.35 * cap {
            score += 6.0 + 2.0 * fitting_bins_count as f64;
        }
        if mean_residual < 8.0 && it > mean_residual {
            score -= 8.0 * remaining;
        }
        if fitting_bins_count > 0 && mean_residual > 0.0 && (mean_residual - it).abs() <= 3.0 {
            score += 18.0;
        }
        if it > 0.6 * cap {
            score -= 9.0 * (0.5 + progress);
        }
        if open_bins_count > 12 && it > 0.7 * cap {
            score -= 6.0;
        }
        // Open a new bin for large items when existing residuals
        // are all too fragmented to chain with the next item.
        if it > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 10.0 * remaining;
        }
        // Dead-gap avoidance: fresh bin when placing on a fitting bin
        // would strand space the next item cannot use.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual > 0.0 {
            let nx = next_item_size as f64;
            let dead = (mean_residual - it).max(0.0);
            if dead > 0.0 && nx > dead {
                score -= (2.5 + 4.5 * remaining) * (dead / mean_residual.max(1.0));
            }
        }
        // Hoard roomy bins for larger future items.
        if open_bins_count > 8 && it < 0.2 * cap && next_item_size as f64 > mean_residual {
            score += 5.0 * remaining;
        }
        // Large next item + small current item: keep fresh bins unfragmented.
        if next_item_size > 0 && fitting_bins_count > 0
            && (next_item_size as f64) > mean_residual * 0.8
            && it < 0.25 * cap {
            score -= 7.0 * remaining;
        }
        // Early stream with big item: fresh bin avoids fragmenting a partial bin.
        if progress < 0.3 && it > 0.55 * cap && fitting_bins_count > 0 {
            score -= 6.0;
        }
        // Exact-fit forecast — if the current item nearly fills a fresh
        // bin to a multiple of the next item size, opening a new bin chains well.
        if next_item_size > 0 && next_item_size <= 20 {
            let post_new = cap - it;
            if post_new >= next_item_size as f64
                && (post_new as u32) % next_item_size <= 3 {
                score -= 9.0 * remaining;
            }
        }
        // When the mean residual is small, leftover bins are nearly
        // useless — prefer consolidating into a fresh bin for medium items.
        if mean_residual > 0.0 && mean_residual < it * 0.45 && it < 0.5 * cap
            && fitting_bins_count >= 2 {
            score -= 4.5 * remaining;
        }
        // NEW: fresh-bin chain value — how many copies of the next item the
        // fresh bin's post-residual can still absorb; more copies, better bin.
        if next_item_size > 0 {
            let post_new = cap - it;
            let copies = (post_new / next_item_size as f64).floor();
            if copies >= 2.0 {
                score -= 3.0 * copies.min(6.0) * remaining;
            }
            // Trap: fresh bin leaves a residual just below the next item size.
            let rem_new = post_new - copies * next_item_size as f64;
            if copies >= 1.0 && rem_new > 0.0 && rem_new < next_item_size as f64 * 0.6 {
                score += 4.0 * rem_new / cap * remaining;
            }
        }
        // NEW: when several bins fit and one of them would end exactly at
        // the next item size, keep the fresh bin closed (defer to it).
        if next_item_size > 0 && fitting_bins_count > 0 && it <= mean_residual * 0.7 {
            score += 6.0 * remaining;
        }
    } else {
        // Tight specialization: penalize drift from mean residual
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += 0.095 * drift;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 9.5 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        if post_residual > 0 && post_residual <= 20 && post_residual >= next_item_size.min(20) {
            score -= 6.5;
        }
        let waste_ratio = pr / cap;
        score += 10.5 * waste_ratio * (0.4 + 0.6 * progress);
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.5 * remaining * (1.0 - pr / cap);
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        if pr > 25.0 && pr < 0.45 * cap {
            score += 3.8 * (pr / cap) * (0.5 + progress);
        }
        // Favor bins whose post-residual matches plausible future item sizes
        if post_residual > 0 && post_residual <= 100 && mean_residual > 0.0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual).min(1.0);
            score -= 3.8 * align;
        }
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * remaining;
        }
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        if bin_residual == item_size {
            score -= 15.0;
        }
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * remaining;
        }
        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * remaining;
        }
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        if post_residual > 0 && mean_residual > 0.0 && post_residual as f64 >= mean_residual * 0.9 {
            score -= 4.0 * remaining;
        }
        if bin_residual as f64 > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        // Penalize residuals that neither the next item nor the mean item
        // can use — pure dead weight, worse early in the stream.
        if post_residual > 0 && next_item_size > 0 && (next_item_size as f64) > post_residual as f64
            && (post_residual as f64) < mean_residual * 0.5 {
            score += 7.0 * remaining;
        }
        // Reward chainable fills: post-residual an exact multiple of a small next item.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && next_item_size <= 12 {
            score -= 6.0 * remaining;
        }
        // Dead-space ratio penalty: stranded residual between half the mean
        // residual and the next item wastes space proportional to its size.
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && pr > mean_residual * 0.5 {
            score += 3.0 * remaining * (pr / mean_residual.max(1.0));
        }
        // Near-exact fills rewarded more when the stream is still long.
        if post_residual > 0 && post_residual <= 6 && next_item_size > 0
            && (next_item_size as f64) >= pr {
            score -= 3.5 * (1.0 + remaining);
        }
        // Post-residual slightly above the mean but below the next item is a trap.
        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Fragmentation pressure — when many bins fit, prefer the one
        // whose post-residual is closest to the next item (best chain start).
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        // Residual that fits next item twice is prime real estate;
        // protect it from being consumed by an oversized current item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
        }
        // NEW: dead-space budget — penalize bins whose post-residual will be
        // stranded (below next item and below mean/2) proportionally to how
        // much of the bin's total space ends up unusable.
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && (post_residual as f64) < mean_residual * 0.5 {
            score += (pr / cap) * 26.0 * remaining;
        }
        // NEW: reward leaving a post-residual that the next item can fill
        // with two or more copies exactly (perfect chain closure).
        if next_item_size > 0 && post_residual > 0 && next_item_size <= 25
            && post_residual % next_item_size == 0
            && post_residual >= 2 * next_item_size {
            score -= 7.5 * remaining;
        }
        // NEW: mid-band residual (just above next item but with small remainder)
        // is worse than a clean split — penalize remainder size explicitly.
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = post_residual % next_item_size;
            if rem > 0 && rem < 5 {
                score += 3.5 * remaining;
            }
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight packing)
    let mut score = post;

    // Non-linear reward for tight fits: quadratic coupling of fill ratio and progress
    let fill_ratio = item / cap;
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * fill_ratio * (0.5 + progress);

    // Penalize unusable dead space: post residual below smallest plausible item (1..100 unknown, use item as proxy)
    let dead = (post / cap).powi(3);
    score += 20.0 * dead * (1.0 - progress);

    // Lookahead: bonus if next item fits exactly in post residual (chained packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let chain_fit = 1.0 - (post - nxt) / cap;
            score -= 8.0 * chain_fit * chain_fit;
        } else {
            // next item won't fit here: slight penalty for leaving awkward residual
            score += 3.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: make it unattractive early/mid stream unless residuals across bins are large
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        // if existing bins are fragmented (high mean residual), a new bin is acceptable
        score += 25.0 * (1.0 - progress) * (1.0 - openness);
        score += 10.0 * (open_bins_count as f64).sqrt().recip();
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Smooth stream-progress coupling: later in stream, prefer tighter packing more aggressively
    score -= 6.0 * progress * (1.0 - post / cap) * (1.0 - post / cap);

    score
}

