pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common small
    // item sizes (10..=20 classes) remain "usable" dead space.
    let pr = post_residual;
    let mut usable = 0.0f64;
    if pr >= 10 {
        if pr % 10 == 0 { usable += 12.0; }
        if pr % 20 == 0 { usable += 8.0; }
        if pr % 25 == 0 { usable += 6.0; }
        if pr % 50 == 0 { usable += 6.0; }
        if pr % 33 == 0 || pr % 34 == 0 { usable += 3.0; }
    } else {
        // Tiny dead space: heavily penalize unusable slivers.
        usable -= 10.0 * (10 - pr) as f64;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            usable += 25.0; // perfect follow-up fit
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 { usable += 10.0; }
            else if gap % 10 == 0 { usable += 5.0; }
            else { usable -= (gap % 10) as f64; }
        } else {
            usable -= 6.0; // next item cannot use this bin's remainder
        }
    }

    // Fractional capacity classes of the bin's fill level.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if (fill * 4.0).round() / 4.0 == fill { usable += 4.0; } // quarter classes
    if (fill * 3.0).round() / 3.0 == fill { usable += 3.0; } // thirds

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        usable += 30.0;
    }

    // Avoid opening new bins when good open candidates exist; prefer new bin
    // only when this bin's post-residual would be very wasteful.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large relative to capacity.
        let big = (item_size as f64 / cap) > 0.6;
        if big { usable -= 8.0; } else { usable += 15.0; }
    }

    // Mild pressure to consolidate when many bins are open.
    usable -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Progress-dependent tightness: later in stream, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score -= usable;
    score
}

