        // NEW: quantify stranded mass directly — the fraction of the bin
        // that will almost certainly never be filled (post_residual smaller
        // than any plausible future item) is penalized super-linearly.
        if post_residual > 0 && mean_residual > 0.0 && next_item_size > 0 {
            let usable = pr >= next_item_size as f64 || pr >= mean_residual;
