        // NEW: pairing bonus — a bin whose post-residual plus the next item
        // lands on a near-multiple of a common small size chains twice.
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size <= 18 {
            let after = post_residual - next_item_size;
            if after > 0 && (after % next_item_size.max(1)) <= 2 {
                score -= 7.0 * remaining;
            }
