    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Residuals that cannot fit the lookahead item are less useful than
    // residuals that could still serve it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than spawning more; penalize new-bin candidate.
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate.
        let pressure = open_bins_count as f64;
        score += 25.0 + pressure * 4.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If no existing bin fits, opening a new bin is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it to avoid a new bin.
        score -= 20.0;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild stream-progress term: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

