        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Fragmentation pressure — when many bins fit, prefer the one
        // whose post-residual is closest to the next item (best chain start).
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        // Residual that fits next item twice is prime real estate;
        // protect it from being consumed by an oversized current item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
        }
        // NEW: dead-space ratio refined — stranded residual weighted by how
        // much of the bin's usable space it represents, plus a sharp penalty
        // when the stranded gap sits just below the next item (worst trap).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let trap = (next_item_size - post_residual) as f64;
            score += remaining * (1.5 + 0.12 * trap) * (pr / cap);
        }
        // NEW: prefer the bin whose post-residual leaves room for a second
        // copy of the next item when several bins fit — multi-chain potential.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= 2 * next_item_size {
            score -= 3.5 * remaining * (1.0 - (post_residual as f64) / cap);
        }
