    } else {
        // Existing bin: slight reward proportional to how far below mean residual
        // it is (favoring fuller bins).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Prefer bins whose residual is just above item size (perfect wedge fits).
    let gap = (bin_residual - item_size) as f64;
    if gap < 5.0 {
        score -= 10.0;
    }

    score
}

