pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    let progress = progress.clamp(0.0, 1.0);

    // Smooth polynomial coupling: post_residual scaled by a progress-dependent
    // polynomial factor (dead space matters more later in the stream).
    let pr = post_residual as f64 / cap;
    let poly = 0.5 + 1.5 * progress * progress + 0.8 * progress * (1.0 - progress);
    score += pr * pr * 40.0 * poly;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize bins whose residual deviates strongly from mean residual
    // (fragmentation indicator), smoothly scaled.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement smoothly; if next item is large and post_residual
    // is small, mild penalty for stranding.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let prr = post_residual as f64;
        if nxt <= prr {
            let fit_gap = (prr - nxt) / cap;
            score -= 18.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            let over = (nxt - prr) / cap;
            score += 10.0 * over * over * (0.3 + 0.7 * progress);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream, with a smooth decay; also scale with number of open bins.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0 * (1.0 - 0.6 * progress) + 2.0 * open_bins_count as f64;
        // If post_residual of new bin is small (item nearly fills it), soften penalty.
        let fill = 1.0 - pr;
        score += new_bin_penalty * (1.0 - 0.5 * fill * fill);
    }

    score
}

