        }
        // Hoard roomy bins for larger future items.
        if open_bins_count > 8 && it < 0.2 * cap && next_item_size as f64 > mean_residual {
            score += 5.0 * remaining;
        }
        if next_item_size > 0 && fitting_bins_count > 0
            && (next_item_size as f64) > mean_residual * 0.8
            && it < 0.25 * cap {
            score -= 7.0 * remaining;
        }
        if progress < 0.3 && it > 0.55 * cap && fitting_bins_count > 0 {
            score -= 6.0;
        }
        // Exact-fit forecast: fresh bin whose post-residual is a near-multiple
        // of the next item chains well.
        if next_item_size > 0 && next_item_size <= 20 {
            let post_new = cap - it;
            if post_new >= next_item_size as f64
                && (post_new as u32) % next_item_size <= 3 {
                score -= 9.0 * remaining;
            }
        }
        if mean_residual > 0.0 && mean_residual < it * 0.45 && it < 0.5 * cap
            && fitting_bins_count >= 2 {
            score -= 4.5 * remaining;
        }
        // NEW: dead-space forecast for the fresh bin itself — if the fresh
        // bin's own post-residual cannot host the next item while some open
        // bin's post-residual could, prefer consolidating there instead.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let post_new = cap - it;
