pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "large dead space" classes get penalized.
    let pr = post_residual;
    // Dead-space class: leftover too small to be useful (below smallest item)
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    }
    // Harmonic fraction classes of capacity: 1/4, 1/3, 1/2 leftovers are reusable
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    if pr >= quarter && pr < quarter + 10 {
        score -= 8.0; // quarter-class residual: very reusable
    }
    if pr >= third && pr < third + 10 {
        score -= 6.0;
    }
    if pr >= half && pr < half + 10 {
        score -= 4.0;
    }
    // Modulo-based waste: leftover that is coprime-ish with typical sizes wastes space
    if pr % 10 != 0 && pr > 0 && pr < 30 {
        score += (pr % 10) as f64 * 1.5;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0 + 0.2 * (pr - next_item_size) as f64;
        } else if pr > 0 {
            // leftover cannot host next item: penalize proportional to waste
            score += 3.0;
        }
        // Exact chaining: post_residual exactly equals next item size
        if pr == next_item_size {
            score -= 12.0;
        }
        // Harmonic pairing: next item complements current to a nice fraction
        let combined = item_size + next_item_size;
        if combined == bin_capacity {
            score -= 15.0;
        } else if combined > bin_capacity {
            score += 2.0;
        }
    } else {
        // Last item: just fill tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if open bins are crowded
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so opening new bins is not preferred over decent fits
        score += cap * 0.6;
        // If mean residual across open bins is small (all crowded), new bin is fine
        if mean_residual < 25.0 {
            score -= cap * 0.5;
        }
        // Late in stream with many bins, discourage proliferation
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 / cap) * 2.0;

    // Mean-residual coupling: if this bin is far below mean residual, it's a good fit target
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

