        // Near-exact fills rewarded more when the stream is still long.
        if post_residual > 0 && post_residual <= 6 && next_item_size > 0
            && (next_item_size as f64) >= pr {
            score -= 3.5 * (1.0 + remaining);
        }
        // Post-residual slightly above the mean but below the next item is a trap.
        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Fragmentation pressure — when many bins fit, prefer the one
        // whose post-residual is closest to the next item (best chain start).
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        // Residual that fits next item twice is prime real estate;
        // protect it from being consumed by an oversized current item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
        }
        // NEW: dead-space efficiency — penalize placing an item into a bin
        // when the resulting post-residual is smaller than the next item by
        // more than the mean item could ever use; scale by how much space
        // is wasted relative to capacity.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && (next_item_size as f64) > mean_residual * 1.5 {
            score += 4.0 * remaining * (pr / cap);
        }
        // NEW: protect large residuals (>= next item) from small items when
        // the next item could fill them exactly — waste ratio guard.
        if next_item_size > 0 && post_residual as u32 == next_item_size && it < 0.2 * cap {
            score -= 4.0 * remaining;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize small-but-usable gaps lightly to encourage tight fits.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Strong preference for exact or near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // encourage filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mildly worse than a good fit, better than a bad one.
        score = 50.0 + pressure;
        // If lookahead item is large, opening a fresh bin may pay off.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // Last-chance alternative makes new bin unattractive.
        if fitting_bins_count == 1 {
            score += 45.0;
