pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: post_residual exactly matches next item -> big reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to overshoot,
            // worse when post_residual is a small unusable sliver.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.25 * overshoot;
            if post_residual < 10 {
                score += 12.0; // dead space penalty
            }
        }
        // Bonus if next item exactly fills the bin after this placement.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * pr;
    }

    // Relative to mean residual: prefer bins with residual below the mean
    // (fill the tightest bins first), penalize above-mean bins slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are crowded; penalize opening new bins when few fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score += 25.0 - 20.0 * progress + 5.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // large incoming pair benefits from fresh bin
        }
    }

    // Late-stream consolidation: discourage scattering across many bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

