        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 13.5;
        }
        if it < 28.0 && open_bins_count > 3 {
            score += 14.5;
        }
        if progress > 0.7 && it < 50.0 {
            score += 11.5 * progress;
        }
        if next_item_size as f64 > 0.5 * cap {
            score += 7.5;
        }
        if next_item_size > 0 && it <= mean_residual {
            score += 5.5 * (1.0 - it / mean_residual);
        }
        if it < 40.0 && mean_residual > 0.0 && (mean_residual - it).abs() < 6.0 {
            score += 10.0;
        }
        if it < 15.0 && fitting_bins_count > 0 {
            score += 22.0;
        }
        if fitting_bins_count >= 3 && it < 0.35 * cap {
            score += 6.0 + 2.0 * fitting_bins_count as f64;
        }
        if mean_residual < 8.0 && it > mean_residual {
            score -= 8.0 * remaining;
        }
        if fitting_bins_count > 0 && mean_residual > 0.0 && (mean_residual - it).abs() <= 3.0 {
            score += 18.0;
        }
        if it > 0.6 * cap {
            score -= 9.0 * (0.5 + progress);
        }
        if open_bins_count > 12 && it > 0.7 * cap {
            score -= 6.0;
        }
        if it > 0.5 * cap && next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 10.0 * remaining;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual > 0.0 {
            let nx = next_item_size as f64;
            let dead = (mean_residual - it).max(0.0);
            if dead > 0.0 && nx > dead {
                score -= (2.5 + 4.5 * remaining) * (dead / mean_residual.max(1.0));
            }
        }
        if open_bins_count > 8 && it < 0.2 * cap && next_item_size as f64 > mean_residual {
            score += 5.0 * remaining;
        }
        if next_item_size > 0 && fitting_bins_count > 0
            && (next_item_size as f64) > mean_residual * 0.8
            && it < 0.25 * cap {
            score -= 7.0 * remaining;
        }
        if progress < 0.3 && it > 0.55 * cap && fitting_bins_count > 0 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size <= 20 {
            let post_new = cap - it;
            if post_new >= next_item_size as f64
                && (post_new as u32) % next_item_size <= 3 {
                score -= 9.0 * remaining;
            }
        }
        if mean_residual > 0.0 && mean_residual < it * 0.45 && it < 0.5 * cap
            && fitting_bins_count >= 2 {
            score -= 4.5 * remaining;
        }
        // NEW: fresh-bin utilization forecast — opening a bin whose own
        // post-residual is a near multiple of the next item chains better
        // than any existing fragmented residual can.
        if next_item_size > 0 && next_item_size <= 25 && it >= next_item_size {
            let chain = (cap - it) % (next_item_size as f64);
            if chain <= 2.0 {
                score -= 5.5 * remaining * (1.0 - it / cap);
            }
        }
        // NEW: when the current item would only leave a thin unusable sliver
        // in the best fitting bin, a fresh bin preserves that sliver for
        // accumulation instead of stranding it.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual > 0.0 {
            let sliver = mean_residual - it;
            if sliver > 0.0 && sliver < (next_item_size as f64) * 0.5 {
                score -= 6.0 * remaining * (1.0 - sliver / (next_item_size as f64).max(1.0));
            }
        }
        // NEW: late-stream small items should consolidate into fresh bins
        // only when open bins are nearly exhausted of usable space.
        if progress > 0.6 && it <= 12.0 && mean_residual > 2.0 * it {
            score += 8.0 * remaining;
        }
    } else {
        // Tight specialization: penalize drift from mean residual
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += 0.095 * drift;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 9.5 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        if post_residual > 0 && post_residual <= 20 && post_residual >= next_item_size.min(20) {
            score -= 6.5;
        }
        let waste_ratio = pr / cap;
        score += 10.5 * waste_ratio * (0.4 + 0.6 * progress);
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.5 * remaining * (1.0 - pr / cap);
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        if pr > 25.0 && pr < 0.45 * cap {
            score += 3.8 * (pr / cap) * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 100 && mean_residual > 0.0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual).min(1.0);
            score -= 3.8 * align;
        }
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * remaining;
        }
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        if bin_residual == item_size {
            score -= 15.0;
        }
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * remaining;
        }
        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * remaining;
        }
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        if post_residual > 0 && mean_residual > 0.0 && post_residual as f64 >= mean_residual * 0.9 {
            score -= 4.0 * remaining;
        }
        if bin_residual as f64 > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        if post_residual > 0 && next_item_size > 0 && (next_item_size as f64) > post_residual as f64
            && (post_residual as f64) < mean_residual * 0.5 {
            score += 7.0 * remaining;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && next_item_size <= 12 {
            score -= 6.0 * remaining;
        }
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && pr > mean_residual * 0.5 {
            score += 3.0 * remaining * (pr / mean_residual.max(1.0));
        }
        if post_residual > 0 && post_residual <= 6 && next_item_size > 0
            && (next_item_size as f64) >= pr {
            score -= 3.5 * (1.0 + remaining);
        }
        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
        }
        // NEW: dead-space ratio — penalize bins whose post-residual is a
        // large fraction of capacity yet smaller than the next item; these
        // strand the most absolute space.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 14.0 * remaining * (pr / cap);
        }
        // NEW: two-step chain check — reward residuals that can absorb the
        // next item AND still leave room for the item after it (approximated
        // by the mean residual).
        if next_item_size > 0 && post_residual > next_item_size
            && (post_residual - next_item_size) as f64 >= mean_residual * 0.6 {
            score -= 4.5 * remaining;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    score -= (cap - post_residual as f64) * 0.35;

    // Strong reward when this is the only bin that can fit the item (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly-ish into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post_residual as f64 - nxt;
        if gap >= 0.0 {
            score -= (1.0 - gap / cap) * 12.0;
        } else {
            // post_residual too small for next item: penalize wasted space
            score += (post_residual as f64 / cap) * 6.0;
        }
    }

    // Penalize opening a new bin when existing bins can fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // The more open bins fit, the worse it is to open a new one.
        score += 30.0 + 8.0 * (fitting_bins_count as f64).min(5.0);
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight penalty when this bin's residual deviates far from mean residual
    // (keeps pool of residuals homogeneous, easing future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer filling nearly-full bins: quadratic bonus for small post_residual.
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
