        score += 10.5 * waste_ratio * (0.4 + 0.6 * progress);
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.5 * remaining * (1.0 - pr / cap);
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        if pr > 25.0 && pr < 0.45 * cap {
            score += 3.8 * (pr / cap) * (0.5 + progress);
        }
        // Favor bins whose post-residual matches plausible future item sizes
        if post_residual > 0 && post_residual <= 100 && mean_residual > 0.0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual).min(1.0);
            score -= 3.8 * align;
        }
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * remaining;
        }
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        if bin_residual == item_size {
            score -= 15.0;
        }
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * remaining;
        }
        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * remaining;
        }
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        if post_residual > 0 && mean_residual > 0.0 && post_residual as f64 >= mean_residual * 0.9 {
            score -= 4.0 * remaining;
        }
        if bin_residual as f64 > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        // Penalize residuals that neither the next item nor the mean item
        // can use — pure dead weight, worse early in the stream.
        if post_residual > 0 && next_item_size > 0 && (next_item_size as f64) > post_residual as f64
            && (post_residual as f64) < mean_residual * 0.5 {
            score += 7.0 * remaining;
        }
        // Reward chainable fills: post-residual an exact multiple of a small next item.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && next_item_size <= 12 {
            score -= 6.0 * remaining;
        }
        // Dead-space ratio penalty on stranded residuals.
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && pr > mean_residual * 0.5 {
            score += 3.0 * remaining * (pr / mean_residual.max(1.0));
        }
        // Near-exact fills rewarded more when the stream is still long.
        if post_residual > 0 && post_residual <= 6 && next_item_size > 0
            && (next_item_size as f64) >= pr {
            score -= 3.5 * (1.0 + remaining);
        }
        // Post-residual slightly above the mean but below the next item is a trap.
        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Fragmentation pressure: with many fitting bins, prefer the one
        // whose post-residual is closest to the next item (best chain start).
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        // Protect prime real estate: residuals that fit the next item twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
