    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: partition sizes into classes by capacity fractions
    let cap = bin_capacity as f64;
    let item_class = (item_size as f64 / cap * 8.0).floor() as i32; // 0..8 harmonic class
    let next_class = if next_item_size == 0 { -1 } else { (next_item_size as f64 / cap * 8.0).floor() as i32 };

    // Reward tight fits: post_residual in low harmonic classes of the bin
    let post = post_residual as f64;
    let post_class = (post / cap * 8.0).floor() as i32;
    score -= (8 - post_class.min(8)) as f64 * 3.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space: residual too small for any plausible future item (min size 1)
    // but large enough to be wasted; use modulo arithmetic on post_residual
    let dead_zone = post_residual % 10;
    if post_residual > 0 && dead_zone > 0 && dead_zone < 3 {
        score += 12.0; // tiny unusable slivers
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
        // Complementary class pairing: classic pairs (1,8),(2,7),(3,6),(4,5) sum to 9
        if item_class + next_class == 9 && post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here; slight penalty unless post_residual is tiny anyway
        if post_residual > 5 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, discourage unless item is huge
    if bin_residual == bin_capacity {
        if item_size as f64 > 0.6 * cap {
            score -= 15.0; // big items better in fresh bins
        } else {
            score += 25.0; // prefer existing bins for small/medium items
        }
    }

    // Prefer filling bins with larger residual relative to mean (balance avoidance)
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Early stream: slightly favor opening bins to build diversity; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0 - progress * 10.0;
    }

    // Integer-division threshold: reward placements leaving residuals in "harmonic" buckets
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 6.0,
        1 => 3.0,
        2 => 1.0,
        _ => 0.0,
    };

    score
}

