    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 25.0;
        // More attractive to open a new bin when item is large relative to capacity.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        // Prefer opening new bins when existing bins are crowded (low mean residual).
        score -= 0.15 * mean_residual;
        // When many bins fit the item, less need for a new bin.
        score += 2.0 * (fitting_bins_count as f64);
        // Late in stream, prefer reusing open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    } else {
        // Mild preference for fuller bins among open bins.
        score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Global pressure: many open bins -> favor consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.3 * (open_bins_count as f64);
    }

    // Small tie-breaker against very large leftover gaps.
    score += 0.02 * post_residual as f64;

    score
}

