    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual in [0,1]

    // Smooth progress-modulated penalty on leftover space: waste matters more later.
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 4.0 * prn * prn * progress_curve * cap;

    // Reward tight fits with a smooth cubic coupling.
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness * tightness * tightness * cap * (0.5 + 0.5 * progress_curve);

    // Last-chance bonus: penalize alternatives so the unique fitting bin is chosen.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = 1.0 - (pr - nxt) / cap;
            score -= 3.0 * fit_ratio * fit_ratio;
        } else {
            // next item won't fit here: mildly penalize creating near-full bins
            score += 2.0 * tightness;
        }
    }

    // Discourage fragmenting bins when mean residual is already low (late-stage packing).
    score += 0.05 * (mean_residual - pr).abs();

    score
}

