pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / 10; // 0..=10 harmonic class
    let band_bonus = match band {
        0 => 40.0,                     // dead space <= 9 : terrible
        1 => 15.0,                     // 10..19 : very poor
        2 => 5.0,                      // 20..29
        3 => -2.0,                     // 30..39 : decent
        4 => -6.0,                     // 40..49
        5 => -8.0,                     // 50..59 : sweet spot
        6 => -6.0,
        7 => -4.0,
        8 => -1.0,
        9 => 3.0,
        _ => 8.0,                      // nearly empty bin used for small item: wasteful
    };
    score += band_bonus;

    // Modulo arithmetic: exact-fill and near-fill rewards
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual % 10 == 0 {
        score -= 10.0; // clean harmonic residual (10,20,...) likely reusable
    }

    // Penalize residuals in "dead zone" classes: 1..9 and 11..19 mod 20 awkward gaps
    let m20 = post_residual % 20;
    if m20 > 0 && m20 < 10 {
        score += (10 - m20) as f64 * 0.8; // small awkward gap penalty
    }

    // Lookahead coupling: does next_item_size fit the post_residual class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward more when next item leaves another clean residual
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 12.0;
            }
            score -= (next_item_size as f64) * 0.15; // reusable residual favored
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let over = next_item_size - post_residual;
            score += (over.min(30) as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // open new bin if item is large relative to capacity (harmonic class of item)
        let item_class = item_size / 20; // 0..4
        match item_class {
            0 => score += 15.0,  // tiny item in new bin: bad
            1 => score += 5.0,
            2 => score -= 0.0,
            3 => score -= 10.0,  // large items pair well with fresh bins
            _ => score -= 18.0,
        }
        // if many open bins with high mean residual, prefer consolidating instead
        score += (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Progression: early in stream, slightly favor tight packing; late, favor consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (mean_residual - post_f).abs() * 0.1;

    // Mild preference for bins below mean residual (balance harvesting)
    if post_f < mean_residual {
        score -= 3.0;
    }

    score
}

