pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual < 10 {
        score += 60.0 - 4.0 * post_residual as f64; // tiny gaps are terrible
    } else if post_residual <= 30 {
        // moderate penalty for smallish gaps, decaying with size
        score += 0.6 * (30.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * next_item_size as f64;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual < 10 {
            // next item would leave near-zero waste if placed here first? penalize blocking
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
