    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; high open_bins_count makes new bins costlier.
        score += 25.0 + 1.5 * open_bins_count as f64;
