    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host typical future items are waste.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Perfect / near-perfect fits get strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    }
    // If next item would NOT fit even in a fresh bin, lookahead is irrelevant; slight penalty otherwise
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0;
