    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        score += 18.0 + crowd * 1.5 + progress * 10.0;
        // If mean residual across bins is large, opening a new bin is wasteful.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
