pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (item_size as f64 / cap); // 0 for big items, ~1 for tiny
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, residual space matters more (waste compounds).
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += pr * pr / cap * prog_poly * 0.8;

    // Reward tight fits (small post_residual) super-linearly.
    score -= (1.0 - pr / cap).powi(3) * cap * 0.25;

    // Penalize dead space that no plausible item can use: post_residual < 10 is dead,
    // but keep it smooth via a sigmoid-like bump.
    let dead = ((10.0 - pr) / 10.0).clamp(0.0, 1.0);
    score += dead * dead * 15.0;

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 12.0;
        // penalize leaving residual slightly larger than next item (unusable sliver)
        if pr > next_item_size as f64 && gap < 10.0 {
            score += (10.0 - gap) * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: open fresh bins early (when few open bins / early stream),
    // penalize opening new bins late or when many bins are already open.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = cap * 0.9 + open_pressure * 40.0 + prog_poly * 30.0;
        // a new bin is attractive if item is large and would leave a useful residual elsewhere
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild preference toward bins below mean residual (balance load) with smooth coupling.
    score += ((bin_residual as f64 - mean_residual) / cap).max(0.0) * 5.0 * (1.0 - tightness);

    score
}

