}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets model "dead space quality".
    let pr = post_residual;
    let class = pr % 10;
    // Perfect fits (0 residual) heavily rewarded.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Penalize residual classes that are hard to fill later (small odd remainders).
        match class {
            0 => score -= 20.0,                 // round residual, reusable
            5 => score -= 8.0,                  // half-decade, mildly reusable
            1 | 3 | 7 | 9 => score += 12.0,     // awkward small remainders
            _ => score += 4.0,
        }
        // Dead-space penalty grows when residual is too small for any plausible item (min size 1, typical >=10).
        if pr < 10 {
            score += 30.0;
        }
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 60.0; // chains a perfect follow-up fit
            } else if gap < 10 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow in this bin: mild penalty scaled by how far off.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when current fit is poor
    // and remaining stream is long enough to justify it.
    if bin_residual == bin_capacity {
        // Empty-bin baseline: slightly worse than a tight fit, better than a wasteful one.
        score = cap * 0.35;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        // Late in the stream, prefer reusing open bins (fewer bins at the end).
        score += progress * 25.0;
        // If many open bins with slack, discourage another.
        if mean_residual > cap * 0.4 && open_bins_count > 2 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin can hold next item too: small bonus early on.
            if progress < 0.5 {
                score -= 10.0;
            }
        }
    }

    // Prefer bins whose residual is close in integer-division class to the item (harmonic match).
    let q_bin = bin_residual / 20;
