    let mut score = post_residual as f64;

    // Hard dead-space zones: residuals that are too small to be useful for
    // typical items are heavily penalized (unusable gap creation).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // almost certainly dead space
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
