    // over opening a new bin (avoids fragmentation pressure).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 2.0;

