            (bin_residual - item_size) as f64 / bin_residual as f64
        } else {
            1.0
        };
        // Penalize opening a new bin generally, but less when fits are poor.
        score += 20.0 + 40.0 * fit_quality;
        // Large items justify a fresh bin more.
        score -= (item_size as f64 - 50.0).max(0.0) * 0.5;
    }

    // Lookahead coupling: if the next item can use the post_residual,
    // reward leaving that gap; otherwise penalize it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins whose post_residual tracks the
