    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Early stream: be slightly more tolerant of opening bins to build
    // flexibility; late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

