    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty if it would have fit pre-placement.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= 8.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is below mean residual (tighter), favor it.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, be conservative with new bins; late, allow consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate logic: only attractive when item is large and no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_competition = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score += 45.0 * no_competition - 35.0 * large_item * progress;
