    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Residuals in "dead" classes (too small for
    // typical items) should be penalized; productive classes rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..=10 harmonic class

    // Dead-space penalty: residual below the smallest plausible item (<= ~12)
    // is nearly unusable -> strong penalty.
    if post_residual < 12 {
        score += 60.0 * (1.0 - frac * 8.0).max(0.0);
    }

    // Reward residuals that lie in "useful" harmonic classes: multiples of
    // common item sizes (mod arithmetic on post_residual).
    let useful_mods: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut mod_bonus = 0.0;
    for m in useful_mods.iter() {
        if post_residual % m == 0 && post_residual > 0 {
            mod_bonus += 8.0;
        }
    }
    score -= mod_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect harmonic pairing -> big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 30.0; // exact fill: bin closed perfectly
        } else {
            // penalize leaving a residual that next item only barely improves
            let pair_post = post_residual - next_item_size;
            if pair_post < 12 {
                score += 20.0; // creates new dead space for the pair
            }
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; residual quality is all that matters
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual is dead space).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 12 {
            score += 10.0; // still bad if it creates dead space
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; do not
    // open a new bin unless current placements are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 35.0;
        // more open bins with high mean residual -> waste, opening new is fine
        if mean_residual > 30.0 && open_bins_count > 2 {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
