        if item_size > 50 {
            score -= 10.0;
        }
    }

    // Prefer tighter fits overall: reward small post_residual relative to mean.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Slight preference for bins whose residual class matches item's class
    // (harmonic affinity via integer division thresholds).
    let item_class = (item_size as f64 / bin_capacity as f64 * 10.0).floor() as i32;
    if class == item_class {
        score -= 6.0;
    }

    score
}

