            score -= 5.5 * remaining;
        }
    } else {
        // Tight specialization
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += 0.095 * drift;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 9.5 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        if post_residual > 0 && post_residual <= 20 && post_residual >= next_item_size.min(20) {
            score -= 6.5;
        }
        let waste_ratio = pr / cap;
        score += 10.5 * waste_ratio * (0.4 + 0.6 * progress);
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.5 * remaining * (1.0 - pr / cap);
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        if pr > 25.0 && pr < 0.45 * cap {
            score += 3.8 * waste_ratio * (0.5 + progress);
        }
        // Favor bins whose post-residual matches plausible future item sizes
        if post_residual > 0 && post_residual <= 100 && mean_residual > 0.0 {
            let align = 1.0 - ((pr - mean_residual).abs() / mean_residual).min(1.0);
            score -= 3.8 * align;
        }
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 12.0 * remaining;
        }
        if post_residual >= 18 && post_residual <= 30 && progress > 0.5 {
            score += 4.5 * progress;
        }
        if bin_residual == item_size {
            score -= 15.0;
        }
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        if bin_residual > item_size && bin_residual - item_size == 1 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            score -= 5.0 * remaining;
        }
        if post_residual > 0 && post_residual < 12 && post_residual < next_item_size {
            score += 8.0 * remaining;
        }
        if post_residual > 0 && post_residual <= 50 && (50 % post_residual.max(1)) <= 2 {
            score -= 5.0;
        }
        if post_residual > 0 && mean_residual > 0.0 && pr >= mean_residual * 0.9 {
            score -= 4.0 * remaining;
        }
        if bin_residual as f64 > 0.5 * cap && it < 0.3 * cap && fitting_bins_count > 1 {
            score += 5.0 * progress;
        }
        // Penalize residuals neither the next item nor mean item can use
        if post_residual > 0 && next_item_size > 0 && (next_item_size as f64) > pr
            && pr < mean_residual * 0.5 {
            score += 7.0 * remaining;
        }
        // Chainable fills: exact multiple of a small next item
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && next_item_size <= 12 {
            score -= 6.0 * remaining;
        }
        // Dead-space ratio penalty
        if post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && pr > mean_residual * 0.5 {
            score += 3.0 * remaining * (pr / mean_residual.max(1.0));
        }
        // Near-exact fills rewarded more when stream is long
        if post_residual > 0 && post_residual <= 6 && next_item_size > 0
            && (next_item_size as f64) >= pr {
            score -= 3.5 * (1.0 + remaining);
        }
        // Post-residual slightly above the mean but below the next item is a trap
        if post_residual > 0 && next_item_size > 0
            && pr > mean_residual
            && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Fragmentation pressure: prefer chain-start post-residuals
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.55 * remaining;
        }
        // Protect prime real estate from oversized current items
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && next_item_size <= 15 && it > 0.4 * cap {
            score -= 4.0 * remaining;
        }
        // NEW: dead-space ratio penalty scaled by how unusable the gap really is —
        // a gap larger than the next item but smaller than mean_residual is a
        // half-dead zone that fragments future packing; punish proportionally.
        if post_residual > 0 && next_item_size > 0
            && (next_item_size as f64) < pr
            && pr < mean_residual * 0.8 {
            score += 4.5 * remaining * (pr / mean_residual.max(1.0));
        }
        // NEW: reward bins whose post-residual is a small multiple of the next item,
        // enabling multi-item chaining (strongest when the stream is long).
        if next_item_size > 0 && post_residual > 0 && next_item_size <= 10
            && post_residual % next_item_size == 0
            && post_residual >= 2 * next_item_size {
            score -= 4.0 * remaining * (post_residual / next_item_size).min(4) as f64;
        }
        // NEW: avoid leaving residuals in the 12..=17 dead band that no typical
        // item can absorb unless it exactly matches the next item size.
        if post_residual >= 12 && post_residual <= 17
            && next_item_size != post_residual {
            score += 3.0 * remaining;
        }
    }

    // Unusable tiny dead space
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // very hard to fill
        } else if post_residual < 35 {
            score += 8.0; // moderately awkward
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing a bin
    }

    // Reward exact matches with the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // can still accommodate the next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // next item won't fit here: dead space likely
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few open
    // bins, opening a new one is cheaper, so new-bin candidate is less penalized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score -= pressure;

    // New-bin candidate handling: it has zero post_residual only if item fills
    // it; otherwise its residual is large. Encourage new bin when current fit
    // creates dead space and few bins are open.
    if bin_residual == bin_capacity {
        // brand-new empty bin: residual after placement is large, so the base
        // score already penalizes it; soften slightly when open bins are few
        // or the current placement would leave a tiny unusable gap.
        if post_residual < 10 && post_residual > 0 {
            score -= 50.0; // opening a new bin beats creating a sliver
        }
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Mild early-stream adjustment: be more tolerant of spreading early.
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    }
    // Near match: post_residual can host next item with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
        // Divisibility bonus: residual can chain multiple future items
        if post_residual % next_item_size <= 4 {
            score -= 14.0;
        }
        if post_residual >= 2 * next_item_size && next_item_size <= 15 {
            score -= 8.0;
        }
    }
    // Dead space: post_residual too small for the next item.
    else if next_item_size > 0 && post_residual > 0 {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.9 * dead.min(40.0) * (0.5 + remaining);
    }

    // Compare against mean residual across open bins.
    score += 0.3 * (pr - mean_residual);

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        score += fitting_bins_count as f64 * 0.3;
    }

    // Avoid wasting nearly-full bins; prefer filling bins tightly.
    if post_residual < 10 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 120.0;
    }

    // Mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 8.0 * remaining;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = 30.0 + 0.5 * mean_residual;
        if fitting_bins_count <= 1 {
            score -= 60.0; // never open a new bin if this is the only fitting bin
        }
        // Early stream: keep fresh bins for future big items
        score += 12.0 - 12.0 * progress - 3.0 * pressure.min(5.0);
        // Small item into fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 3 {
            score += 16.0;
        }
        // Large item late in stream: fresh bin is fine
        if progress > 0.6 && it > 0.55 * cap {
            score -= 9.0 * progress;
        }
        // Fresh bin whose post-residual exactly fits next item
        if next_item_size > 0 {
            let post_new = cap - it;
            if post_new >= next_item_size as f64 {
                score -= 10.0 * remaining;
                if (post_new as u32) % next_item_size <= 3 {
                    score -= 8.0;
                }
            } else {
                score += 6.0; // fresh bin would strand the next item
            }
        }
        // Mean residual close to item size: existing bins fit well already
        if mean_residual > 0.0 && (mean_residual - it).abs() <= 4.0 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Hoard roomy bins when mean residual is large
        if mean_residual > 0.4 * cap && it < 0.35 * cap {
            score += 8.0 * remaining;
        }
        // Fragmented state: consolidate with a fresh bin
        if open_bins_count > 10 && mean_residual < 10.0 && it > 20.0 {
            score -= 6.0 * remaining;
        }
    } else {
        // Penalize drift from mean residual slightly
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * drift;
        // Near-exact fill reward
        if bin_residual == item_size {
            score -= 12.0;
        } else if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 6.0;
        }
        // Waste ratio grows in weight as stream progresses
        score += 9.0 * (pr / cap) * (0.4 + 0.6 * progress);
        // Trap: residual above mean but below next item is hard to use
        if next_item_size > 0 && post_residual > 0 && pr > mean_residual && post_residual < next_item_size {
            score += 6.0 * remaining;
        }
        // Chain-start post-residuals preferred
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += gap * 0.5 * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let left = post_residual - next_item_size;
            // reward tight chain fits, penalize large leftover after next item
            score -= 100.0 - left as f64 * 1.5;
            if left == 0 {
                score -= 400.0;
            }
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual against mean residual of open bins
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: prefer opening a fresh bin when item is large
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 150.0;
        } else {
            score += 100.0;
        }
        // less eager to open new bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Penalize leaving large dead space in a nearly full bin
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 20.0;
    }

    score
}

