    }

    // Unusable tiny dead space
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual gets bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; slight penalty.
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Mild penalty when many alternatives (prefer best fit among them).
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer fuller bins relative to the mean residual (pack tight bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: favor existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that shrinks if item is huge
        // and current bins would be badly fragmented.
        let mut new_bin_score = 30.0 + 20.0 * progress;
        // Big items with no good chain: opening fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        if post_residual == 0 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Placing in an existing bin gets progressively rewarded over time.
        score -= 5.0 * progress;
    }

    // Mild pressure against proliferating many open bins with high mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

