}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr)
        - 18.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Reward near-perfect fits more strongly as the stream advances
    score -= 25.0 * progress * (1.0 - norm_pr * norm_pr);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((pr - nx) / cap).max(0.0);
        score += 12.0 * gap * gap * (1.0 - progress);
        score -= 8.0 * (1.0 - gap.abs()) * (nx / cap) * progress;
    }

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Spread pressure: mildly prefer bins below mean residual early, above late
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (2.0 * progress - 1.0);

    // Mild penalty for opening many bins early
    score += 3.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

