pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets dead-space quality
    let harmonic = post_residual % 10;
    score -= (10 - harmonic) as f64 * 0.8; // reward residuals that are "round" (mod 10 == 0)

    // Integer-division thresholds on post_residual: classify dead space
    let small = (post_residual / 10) as f64;
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 6.0 * small / 2.0;
    } else if post_residual > 50 {
        score += 5.0; // wasteful large residual
    }

    // Capacity fraction coupling
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac * std::f64::consts::PI).sin() * 3.0;

    // Lookahead harmonic: can next item land on a harmonic boundary?
    if next_item_size > 0 {
        let combo = post_residual % (next_item_size.max(1));
        if combo == 0 {
            score -= 12.0; // next item exactly fills residual
        } else {
            score += combo as f64 * 0.15;
        }
        if next_item_size <= post_residual {
            score -= 4.0;
        }
    } else {
        score -= 8.0; // last item: prefer tightest fill
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 40.0 + pressure * 30.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Stream progression: tighten selection late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

