pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item (1) are pure waste; small-but-usable gaps are
    // penalized extra if they can't hold the upcoming item.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (smaller than the classic min size 10).
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap can't host the lookahead item: likely future dead space.
        score += 12.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Gap exactly hosts the next item: great pairing.
        score -= 20.0;
    }

    // Tightness reward: the fuller the bin, the better.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; scales with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(0.8) * (0.3 + 0.4 * progress);

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current
    // item is large relative to typical residual or open bins are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let fragmented = mean_residual > 30.0 && open_bins_count > 2;
        if large_item || fragmented {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    score
}

