            score -= 4.0 * remaining;
        }
    }

    // Penalize unusable tiny dead space, scaled by remaining stream
    if post_residual > 0 && post_residual < 9 {
        score += 19.5 + 8.0 * remaining;
    }

    // Penalize mid-range dead zones unusable by the next item
    if post_residual > 11 && post_residual < 25 && next_item_size as u32 > post_residual {
        score += 9.0 * remaining;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Quadratic dead-space penalty: small post_residual is great, large is bad
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Perfect-fit reward (smooth cubic falloff)
    let fit_quality = 1.0 - norm_pr;
    score -= 6.0 * fit_quality * fit_quality * fit_quality * (item_size as f64);

    // Reward filling a bin that becomes nearly full (post_residual small relative to item)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 3.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space that the next item cannot use
        score += 2.0 * (next_item_size as f64 - pr) / cap * 10.0;
    }

    // Penalize spreading across many open bins late in the stream
    score += (open_bins_count as f64) * (0.3 + 0.7 * progress) * (pr / cap);

    // Mild attraction to bins with residuals near the item (smooth kernel)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 2.0 * diff * diff;

    score
}

